func nativeBuildPreparer(o Options) corev1.Container {
	env, keys := indexedLiteralEnv(BuildLiterals(o.BuildEnv), nativeLiteralEnvPrefix)
	env = append(env,
		corev1.EnvVar{Name: "BEX_NATIVE_DOCKERFILE", Value: nativeDockerfile(o)},
		corev1.EnvVar{Name: "BEX_NATIVE_LITERAL_KEYS", Value: keys},
		corev1.EnvVar{Name: "BEX_NATIVE_FILES", Value: strings.Join(o.NativeFiles, "\n")},
	)

	mounts := []corev1.VolumeMount{{Name: "native-build", MountPath: "/native"}}
	if o.RuntimeEnvSecret != "" {
		mounts = append(mounts, corev1.VolumeMount{Name: runtimeEnvVolume, MountPath: "/runtime-env", ReadOnly: true})

// run unchanged on every reviewed toolchain base; the pin is a multi-arch
// index (linux/amd64 + linux/arm64), inventoried in toolchain-freshness.json.
const nativeFFmpegImage = "mwader/static-ffmpeg:9.0.2-1@sha256:f5d100184884eb3e82b0eb14bb5ebf98da99826ac824989720297fb9ef21c822"

// nativeMediaTools is the generated step that puts ffmpeg and ffprobe on the
// image PATH before the source and the authored build, so the build, the
// pre-deploy step and the started service all find them; a static site's
// build does too, as on Render. The binaries are copied to / because a
// --link copy that creates no parent directory is byte-reproducible: every
// native image, on every base and build, then carries the same ~110 MB layer,
// which the registry stores once and a node pulls once (a copy into
// /usr/local/bin recreates those directories with the build's timestamps and
// so is a new blob each time). The links are a few bytes on top. It follows
// the base's other generated steps, so a pin change rebuilds nothing before
// it.
const nativeMediaTools = "COPY --link --from=" + nativeFFmpegImage + " /ffmpeg /ffprobe /\n" +
	"RUN ln -sf /ffmpeg /usr/local/bin/ffmpeg && ln -sf /ffprobe /usr/local/bin/ffprobe\n"

func ResolveNativeBuild(runtime, bundlePath, dockerfilePath, sourceDir string) ([]NativeChoice, error) {
	env, err := readEnvBundle(bundlePath)
	if err != nil {
		return nil, err
	}
	readFile := func(name string) ([]byte, bool) { return readVersionFile(sourceDir, name) }
	choice, err := ResolveNativeVersion(runtime, env, readFile)
	if err != nil {
		return nil, err
	}
	bun, withBun, err := ResolveNativeBun(env, readFile)
	if err != nil {
		return nil, err
	}
	dockerfile, err := os.ReadFile(dockerfilePath)
	if err != nil {
		return nil, fmt.Errorf("read generated Dockerfile: %w", err)
	}
	rewritten, err := rewriteNativeBase(string(dockerfile), nativeToolchains[runtime].defaultImage(), choice.Image)
	if err != nil {
		return nil, err
	}
	choices := []NativeChoice{choice}
	if runtime == nativePythonRuntime {
		poetry, err := ResolveNativePoetry(env)
		if err != nil {
			return nil, err
		}
		uv, withUV, err := ResolveNativeUV(env, readFile)
		if err != nil {
			return nil, err
		}
		// Each step lands right after the FROM, so uv goes in first to follow
		// Poetry's layer, which a uv version change then leaves cached.
		if withUV {
			if rewritten, err = addNativeUV(rewritten, choice.Image, uv.Line); err != nil {
				return nil, err
			}
		}
		if rewritten, err = addNativePoetry(rewritten, choice.Image, poetry.Line); err != nil {
			return nil, err
		}
		choices = append(choices, poetry)
		if withUV {
			choices = append(choices, uv)
		}
	}
	if nativeJSCompanionRuntimes[runtime] {
		node, err := ResolveNativeVersion(nativeNodeRuntime, env, readFile)
		if err != nil {
			return nil, err
		}
		if rewritten, err = addNativeJSTools(rewritten, choice.Image, node.Image); err != nil {
			return nil, err
		}
		choices = append(choices, node)
	}
	if withBun {
		if rewritten, err = addNativeBun(rewritten, choice.Image, bun.Image); err != nil {
			return nil, err
		}
		choices = append(choices, bun)
	}
	if err := os.WriteFile(dockerfilePath, []byte(rewritten), 0o600); err != nil {
		return nil, fmt.Errorf("write generated Dockerfile: %w", err)
	}
	return choices, nil
}

func buildctlRecipeArgs(o Options, dockerfileDir string) []string {
	if o.Builder != BuilderNative {
		args := []string{"--local", "dockerfile=" + dockerfileDir}
		if o.DockerfilePath != "" {
			args = append(args, "--opt", "filename="+o.DockerfilePath)
		}
		return append(args, dockerBuildSecretArgs(o)...)
	}
	args := []string{
		"--local", "dockerfile=/native",
		"--opt", "filename=Dockerfile",
		"--secret", "id=render-env,src=/native/render-env",
	}
	for i, name := range o.NativeFiles {
		args = append(args, "--secret", "id="+nativeFileSecretID(i)+",src=/native/files/"+name)
	}
	if nativeServingInit(o) {
		args = append(args,
			"--local", nativeInitContext+"="+nativeInitDir,
			"--opt", "context:"+nativeInitContext+"=local:"+nativeInitContext,
		)
	}
	return args
}

